from datetime import date
from typing import List, Dict, Tuple

class Loyalty:
    def __init__(self) -> None:
        # Store purchases as {customer: [(amount, purchase_date, points_earned), ...]}
        self._purchases: Dict[str, List[Tuple[float, date, int]]] = {}
        # Store redemptions as {customer: [(points_redeemed, redemption_date), ...]}
        self._redemptions: Dict[str, List[Tuple[int, date]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        # Calculate points: 1 point for every full 10.00 spent
        points = int(amount // 10.0)

        # Initialize customer records if they don't exist
        if customer not in self._purchases:
            self._purchases[customer] = []
        if customer not in self._redemptions:
            self._redemptions[customer] = []

        # Record the purchase
        self._purchases[customer].append((amount, day, points))

        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        # Get all purchases for this customer
        purchases = self._purchases.get(customer, [])

        # Calculate total points from purchases that are at least 14 days old
        available_points = 0
        for amount, purchase_date, points in purchases:
            # Check if purchase is at least 14 days old (available after 14 days)
            # So purchase_date + 14 days <= day means it's available
            days_diff = (day - purchase_date).days
            if days_diff >= 14:
                available_points += points

        # Subtract points that have been redeemed on or before this day
        redemptions = self._redemptions.get(customer, [])
        for points_redeemed, redemption_date in redemptions:
            if redemption_date <= day:
                available_points -= points_redeemed

        # Ensure balance is never negative
        return max(0, available_points)

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points for a customer on a given day."""
        # Get current available balance
        available = self.balance(customer, day)

        if points > available:
            raise ValueError("Not enough points available for redemption")

        # Initialize customer redemptions list if it doesn't exist
        if customer not in self._redemptions:
            self._redemptions[customer] = []

        # Record the redemption
        self._redemptions[customer].append((points, day))
